INSERT INTO shapes (id, name, bias, premium, risk, summary, legs, strike_order, default_deltas, written_by) VALUES
  ('iron_condor', 'Iron condor', 'neutral', 'credit', 'defined', 'Range-bound income with capped risk. `delta` picks both short strikes; `width` sets both wings.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"delta":0.16},"knob":"delta"}},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"wing":"short_put","dir":"down"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.16},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"long_call","strike":{"wing":"short_call","dir":"up"}}]', '[["short_put","short_call"]]', '[0.1, 0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('iron_butterfly', 'Iron butterfly', 'neutral', 'credit', 'defined', 'Pin-the-strike income; larger credit than a condor, narrower profit zone.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","strike":{"same":"short_strike"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_strike","strike":{"pick":{"atm":true},"knob":"none"}},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"wing":"short_strike","dir":"down"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"long_call","strike":{"wing":"short_strike","dir":"up"}}]', '[]', NULL, 'seed'),
  ('short_strangle', 'Short strangle', 'short_volatility', 'credit', 'undefined', 'Undefined-risk premium selling on both sides.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"put","strike":{"pick":{"delta":0.16},"knob":"delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"call","strike":{"pick":{"delta":0.16},"knob":"delta"}}]', '[["put","call"]]', '[0.1, 0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('long_strangle', 'Long strangle', 'long_volatility', 'debit', 'defined', 'Cheaper long-volatility bet than a straddle; needs a bigger move.', '[{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"put","strike":{"pick":{"delta":0.25},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"call","strike":{"pick":{"delta":0.25},"knob":"delta"}}]', '[["put","call"]]', '[0.2, 0.25, 0.3]', 'seed'),
  ('short_straddle', 'Short straddle', 'short_volatility', 'credit', 'undefined', 'Maximum premium, undefined risk both sides.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","strike":{"same":"strike"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"strike","strike":{"pick":{"atm":true},"knob":"none"}}]', '[]', NULL, 'seed'),
  ('long_straddle', 'Long straddle', 'long_volatility', 'debit', 'defined', 'Pure long volatility; profits from a large move either way.', '[{"action":"buy","instrument":"put","qty":1,"expiry":"front","strike":{"same":"strike"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"strike","strike":{"pick":{"atm":true},"knob":"none"}}]', '[]', NULL, 'seed'),
  ('bull_put_spread', 'Bull put spread (put credit spread)', 'bullish', 'credit', 'defined', 'Bullish credit spread. `delta` picks the short put.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"delta":0.3},"knob":"delta"}},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"wing":"short_put","dir":"down"}}]', '[]', '[0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('bear_call_spread', 'Bear call spread (call credit spread)', 'bearish', 'credit', 'defined', 'Bearish credit spread. `delta` picks the short call.', '[{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.3},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"long_call","strike":{"wing":"short_call","dir":"up"}}]', '[]', '[0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('bull_call_spread', 'Bull call spread (call debit spread)', 'bullish', 'debit', 'defined', 'Bullish debit spread. `delta` picks the long call (default 0.50 ≈ ATM).', '[{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"long_call","strike":{"pick":{"delta":0.5},"knob":"delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"wing":"long_call","dir":"up"}}]', '[]', '[0.5, 0.6]', 'seed'),
  ('bear_put_spread', 'Bear put spread (put debit spread)', 'bearish', 'debit', 'defined', 'Bearish debit spread. `delta` picks the long put (default 0.50 ≈ ATM).', '[{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"pick":{"delta":0.5},"knob":"delta"}},{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"wing":"long_put","dir":"down"}}]', '[]', '[0.5, 0.6]', 'seed'),
  ('jade_lizard', 'Jade lizard', 'bullish', 'credit', 'undefined', 'Short put + bear call spread. When total credit ≥ call-spread width there is no upside risk (flagged in notes). `delta` sets both short legs.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"delta":0.3},"knob":"delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.2},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"long_call","strike":{"wing":"short_call","dir":"up"}}]', '[["short_put","short_call"]]', '[0.2, 0.25, 0.3]', 'seed'),
  ('reverse_jade_lizard', 'Reverse jade lizard (twisted sister)', 'bearish', 'credit', 'undefined', 'Short call + bull put spread. When credit ≥ put-spread width there is no downside risk. `delta` sets both short legs.', '[{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.3},"knob":"delta"}},{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"delta":0.2},"knob":"delta"}},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"wing":"short_put","dir":"down"}}]', '[["short_put","short_call"]]', '[0.2, 0.25, 0.3]', 'seed'),
  ('call_butterfly', 'Long call butterfly', 'neutral', 'debit', 'defined', 'Low-cost bet on a pin at the body. Body defaults to ATM (or `delta`/`otm_pct`); `width` sets both wings. Uneven explicit wings = broken-wing butterfly.', '[{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"lower","strike":{"wing":"body","dir":"down"}},{"action":"sell","instrument":"call","qty":2,"expiry":"front","role":"body","strike":{"pick":{"atm":true},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"front","role":"upper","strike":{"wing":"body","dir":"up"}}]', '[]', NULL, 'seed'),
  ('put_butterfly', 'Long put butterfly', 'neutral', 'debit', 'defined', 'Low-cost bet on a pin at the body. Body defaults to ATM (or `delta`/`otm_pct`); `width` sets both wings. Uneven explicit wings = broken-wing butterfly.', '[{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"lower","strike":{"wing":"body","dir":"down"}},{"action":"sell","instrument":"put","qty":2,"expiry":"front","role":"body","strike":{"pick":{"atm":true},"knob":"delta"}},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"upper","strike":{"wing":"body","dir":"up"}}]', '[]', NULL, 'seed'),
  ('zebra_call', 'ZEBRA (bullish)', 'bullish', 'debit', 'defined', 'Zero Extrinsic Back Ratio: ~100-delta stock replacement with little extrinsic paid. `long_delta` sets the ITM leg (default 0.70); the short leg is ATM unless `delta`/strikes given. Check net extrinsic in notes.', '[{"action":"buy","instrument":"call","qty":2,"expiry":"front","role":"long_call","strike":{"pick":{"delta":0.7},"knob":"long_delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"atm":true},"knob":"delta"}}]', '[["long_call","short_call"]]', NULL, 'seed'),
  ('zebra_put', 'ZEBRA (bearish)', 'bearish', 'debit', 'defined', 'Zero Extrinsic Back Ratio: ~100-delta stock replacement with little extrinsic paid. `long_delta` sets the ITM leg (default 0.70); the short leg is ATM unless `delta`/strikes given. Check net extrinsic in notes.', '[{"action":"buy","instrument":"put","qty":2,"expiry":"front","role":"long_put","strike":{"pick":{"delta":0.7},"knob":"long_delta"}},{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"atm":true},"knob":"delta"}}]', '[["short_put","long_put"]]', NULL, 'seed'),
  ('cash_secured_put', 'Cash-secured put', 'bullish', 'credit', 'undefined', 'Get paid to wait to buy shares. capital_required ≈ strike × 100 − credit.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"short_put","strike":{"pick":{"delta":0.3},"knob":"delta"}}]', '[]', '[0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('covered_call', 'Covered call', 'bullish', 'credit', 'undefined', 'Income on held stock; upside capped at the short strike. Stock leg priced at spot.', '[{"action":"buy","instrument":"stock","qty":100},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.3},"knob":"delta"}}]', '[]', '[0.16, 0.2, 0.25, 0.3]', 'seed'),
  ('collar', 'Collar', 'neutral', 'either', 'defined', 'Protect held stock; the short call finances the put. `delta` applies to both options.', '[{"action":"buy","instrument":"stock","qty":100},{"action":"buy","instrument":"put","qty":1,"expiry":"front","role":"long_put","strike":{"pick":{"delta":0.25},"knob":"delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.25},"knob":"delta"}}]', '[]', '[0.2, 0.25, 0.3]', 'seed'),
  ('call_calendar', 'Call calendar', 'neutral', 'debit', 'defined', 'Time-decay / long-vega spread. Strike defaults to ATM (or `delta`/`otm_pct`/strikes.strike). P&L is measured at the front expiry.', '[{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"strike","strike":{"pick":{"atm":true},"knob":"delta"}},{"action":"buy","instrument":"call","qty":1,"expiry":"back","strike":{"same":"strike"}}]', '[]', NULL, 'seed'),
  ('put_calendar', 'Put calendar', 'neutral', 'debit', 'defined', 'Time-decay / long-vega spread. Strike defaults to ATM (or `delta`/`otm_pct`/strikes.strike). P&L is measured at the front expiry.', '[{"action":"sell","instrument":"put","qty":1,"expiry":"front","role":"strike","strike":{"pick":{"atm":true},"knob":"delta"}},{"action":"buy","instrument":"put","qty":1,"expiry":"back","strike":{"same":"strike"}}]', '[]', NULL, 'seed'),
  ('pmcc', 'Poor man''s covered call (call diagonal)', 'bullish', 'debit', 'defined', 'Covered-call payoff for less capital. `long_delta` sets the back-month call (default 0.80); `delta` sets the short front call (default 0.30).', '[{"action":"buy","instrument":"call","qty":1,"expiry":"back","role":"long_call","strike":{"pick":{"delta":0.8},"knob":"long_delta"}},{"action":"sell","instrument":"call","qty":1,"expiry":"front","role":"short_call","strike":{"pick":{"delta":0.3},"knob":"delta"}}]', '[["long_call","short_call"]]', '[0.2, 0.25, 0.3]', 'seed');
