-- StrategyDesk shapes (Bikram, 2026-10-09): the structures an option strategy starts from (iron condor,
-- jade lizard, ...). Shared by every signed-in caller; agents add their own with shape_write. `legs` is
-- JSON: [{action, instrument, qty, expiry, role, strike}] where strike is {pick, knob}, {wing, dir} or
-- {same} (see packages/ts/strategies/src/shape.ts). `strike_order` lists role pairs whose strikes rise.
CREATE TABLE shapes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  bias TEXT NOT NULL CHECK (bias IN ('bullish', 'bearish', 'neutral', 'long_volatility', 'short_volatility')),
  premium TEXT NOT NULL CHECK (premium IN ('credit', 'debit', 'either')),
  risk TEXT NOT NULL CHECK (risk IN ('defined', 'undefined')),
  summary TEXT NOT NULL,
  legs TEXT NOT NULL,
  strike_order TEXT NOT NULL DEFAULT '[]',
  default_deltas TEXT,
  written_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

